/** A top-level window. handle is the HWND as a decimal string (JS numbers cannot hold 64-bit values). */
export interface WindowRef {
  handle: string;
  title: string;
  appId: string;
  iconUrl: string;
  thumbUrl?: string;
  minimized: boolean;
  maximized: boolean;
  active: boolean;
  desktopId?: string;
  /** The window's process runs elevated: the shell (not elevated) cannot activate/minimise/close it (UIPI). UI shows a hint. */
  elevated: boolean;
}

