/** Events pushed from the host to the UI: type -> payload. */
export interface HostEvents {
  /** The installed-app catalog changed (install/uninstall). */
  'apps.changed': AppList;
  /** The host shows/hides the surface window (fullscreen app, overlay open, ...). */
  'surface.visibility': SurfaceVisibility;
  'theme.changed': ThemeState;
  /** Full settings after any change (from any surface, file edit, or reset). */
  'settings.changed': Settings;
  /** Settings window is already open: switch to this page. */
  'settings.navigate': SettingsOpenParams;
  /** The effective UI locale changed (settings.general.language). SurfaceInit.locale carries the initial value. */
  'locale.changed': LocaleState;
  'desktop.state': DesktopState;
  'reminders.changed': ReminderList;
  /** A reminder's due time passed (fires once). */
  'reminders.due': Reminder;
  /** Published by the HOST (SurfaceManager) after it has shown/positioned the overlay window; never posted to a page that has not completed surface.ready. */
  'overlay.show': OverlayShow;
  /** Published by the HOST when IT hides the overlay (hotkey toggle, deactivation, monitor change). */
  'overlay.hide': void;
  /** Streamed: fast providers answer first, files later. Ignore events whose requestId is not the latest. */
  'search.results': SearchResults;
  'status.battery': BatteryState;
  'status.network': NetworkState;
  'status.audio': AudioState;
  'status.brightness': BrightnessState;
  'status.bluetooth': BluetoothState;
  'media.state': MediaState;
  /** Third-party notification-area icons (needs features.trayHosting; otherwise supported=false). */
  'tray.state': TrayState;
  /** Foreground app (ignoring BetterWindows' own windows). Drives the menu bar app name. */
  'activeApp.changed': ActiveAppState;
  /** Full dock model; pushed on any window/pin/settings change (coalesced to >=50 ms). */
  'dock.state': DockState;
  /** Auto-hide: host detected the pointer at the dock edge (true) or leaving (false). */
  'dock.reveal': DockRevealState;
  'dock.bounce': DockBounce;
  /** A thumbnail became available after mc.snapshot. */
  'mc.thumbnail': McThumbnail;
  /** Pushed to the overlay while mode=missionControl is shown whenever windows or desktops change (coalesced >= 100 ms). mc.thumbnail still fills in thumbnails. */
  'mc.changed': McSnapshot;
}

/** Events sent from the UI to the host (fire-and-forget): type -> payload. */
export interface UiEvents {
  /** Dock only: the UI asks for a window of this DIP size (bar + headroom); the host clamps, keeps it centred on its edge, and re-reserves the AppBar for barThickness only. Sent when content/headroom changes. */
  'surface.resize': SurfaceResizeParams;
  /** UI log line, forwarded to the host log. */
  'surface.log': LogParams;
  /** The UI reports its glass panels. Host contract (normative): window region = union(rects, hitRects) in physical px (DIP x scale) via SetWindowRgn for dock/menubar only (never overlay/settings; desktop has no region); backdrop = DWMWA_SYSTEMBACKDROP_TYPE (acrylic/transient) on Windows 11 22H2+ (undocumented accent only behind a feature flag on older builds); DwmEnableBlurBehindWindow MUST NOT be used (it does not blur since Windows 8). Re-send whenever panels move/resize; the host debounces. */
  'surface.shape': SurfaceShapeParams;
}

/** Request/response calls (UI -> host): type -> { params, result }. */
export interface Calls {
  'apps.list': { params: void; result: AppList };
  /** Launch a catalog or running app by id (no arguments are ever accepted from the UI). Unknown ids -> notFound. */
  'apps.launch': { params: AppLaunchParams; result: void };
  /** Show the app's exe/shortcut in Explorer. */
  'apps.reveal': { params: AppIdParams; result: void };
  /** First message every surface sends. After replying the host pushes all current state events to this surface. */
  'surface.ready': { params: SurfaceReadyParams; result: SurfaceInit };
  'settings.get': { params: void; result: Settings };
  /** Deep-merge, validate/clamp, persist, broadcast settings.changed, return the result. */
  'settings.patch': { params: SettingsPatchParams; result: Settings };
  /** Open (or focus) the settings window, optionally on a page. */
  'settings.openWindow': { params: SettingsOpenParams; result: void };
  'desktop.moveIcon': { params: DesktopMoveParams; result: void };
  'desktop.open': { params: IdParams; result: void };
  'desktop.addShortcut': { params: AddShortcutParams; result: DesktopIcon };
  'desktop.removeShortcut': { params: IdParams; result: void };
  'desktop.setWallpaper': { params: SetWallpaperParams; result: void };
  'desktop.moveWidget': { params: MoveWidgetParams; result: void };
  'desktop.addWidget': { params: AddWidgetParams; result: WidgetInstance };
  'desktop.removeWidget': { params: IdParams; result: void };
  'desktop.updateWidget': { params: UpdateWidgetParams; result: WidgetInstance };
  'weather.get': { params: WeatherGetParams; result: WeatherSnapshot };
  'weather.search': { params: WeatherSearchParams; result: WeatherLocations };
  'weather.setLocation': { params: WeatherLocation; result: void };
  'reminders.list': { params: void; result: ReminderList };
  'reminders.add': { params: ReminderAddParams; result: Reminder };
  'reminders.update': { params: ReminderUpdateParams; result: Reminder };
  'reminders.remove': { params: IdParams; result: void };
  /** Any surface asks the host to open the overlay (e.g. menubar -> controlCenter popover). Anchor is translated to overlay coordinates. */
  'overlay.open': { params: OverlayRequest; result: void };
  /** UI-initiated hide: the UI plays its exit animation, THEN calls overlay.close {token}. Host-initiated hides (hotkey toggle, deactivation, monitor change) post overlay.hide and raise ISurfaceManager.OverlayHidden. */
  'overlay.close': { params: OverlayCloseParams; result: void };
  /** Starts a search; results arrive as search.results. Starting a new query cancels the previous one. */
  'search.query': { params: SearchQueryParams; result: void };
  'search.cancel': { params: SearchCancelParams; result: void };
  'search.perform': { params: SearchPerformParams; result: void };
  /** Shown when the query is empty. */
  'search.recent': { params: void; result: SearchRecent };
  /** Lazy preview for the selected result (text file head, image thumbnail url, ...). kind=none if unavailable. */
  'search.preview': { params: SearchPreviewParams; result: SearchPreview };
  'audio.setVolume': { params: VolumeParams; result: void };
  'audio.setMuted': { params: MuteParams; result: void };
  'audio.setDevice': { params: AudioDeviceParams; result: void };
  'brightness.set': { params: BrightnessParams; result: void };
  /** Equivalent to settings.patch { appearance: { mode } }. It NEVER writes the Windows theme. */
  'theme.setPreference': { params: ThemePreferenceParams; result: void };
  'media.control': { params: MediaControlParams; result: void };
  'tray.click': { params: TrayClickParams; result: void };
  'system.power': { params: PowerParams; result: void };
  'system.open': { params: OpenParams; result: void };
  /** ALWAYS restores the taskbar and desktop icons, then exits. */
  'system.quit': { params: void; result: void };
  /** Temporarily show/hide the native taskbar without changing settings. */
  'system.showTaskbar': { params: ShowTaskbarParams; result: void };
  'system.about': { params: void; result: AboutInfo };
  /** Runs every platform self-check (also: BetterWindows.exe --diagnose). */
  'diag.report': { params: void; result: DiagReport };
  /** Native open dialog owned by the calling surface's window (the UI cannot obtain filesystem paths any other way: <input type=file> and drag&drop give no path). The dialog is modal to the settings window; other surfaces may not call it (BadRequest). */
  'system.pickPath': { params: PickPathParams; result: PickPathResult };
  /** All connected monitors (for per-monitor wallpaper/widget pickers in the settings window). */
  'system.monitors': { params: void; result: MonitorList };
  /** Launch if not running; else focus the most recent window (restore if minimised); folders open in Explorer. */
  'dock.activate': { params: DockItemParams; result: void };
  'dock.activateWindow': { params: WindowHandleParams; result: void };
  'dock.closeWindow': { params: WindowHandleParams; result: void };
  /** Pin by app id (from the catalog or a running app). index = position in settings.dock.pins; folders are always appended after apps. */
  'dock.pin': { params: DockPinParams; result: void };
  'dock.unpin': { params: DockItemParams; result: void };
  'dock.reorder': { params: DockReorderParams; result: void };
  'dock.newWindow': { params: DockItemParams; result: void };
  /** Close all windows of the app (WM_CLOSE). itemId may be ANY running app id, not only a visible dock item (used by the app menu). */
  'dock.quit': { params: DockItemParams; result: void };
  /** Minimise all windows of the app. itemId may be ANY running app id (used by the app menu). */
  'dock.hide': { params: DockItemParams; result: void };
  'dock.revealInExplorer': { params: DockItemParams; result: void };
  'mc.snapshot': { params: McSnapshotParams; result: McSnapshot };
  'mc.activateWindow': { params: WindowHandleParams; result: void };
  'mc.closeWindow': { params: WindowHandleParams; result: void };
  'mc.switchDesktop': { params: DesktopIdParams; result: void };
  'mc.moveWindow': { params: McMoveParams; result: void };
  'mc.createDesktop': { params: void; result: DesktopInfo };
  'mc.removeDesktop': { params: DesktopIdParams; result: void };
  /** Pin a folder / exe / lnk by path (folders become kind=folder items, exe/lnk become app items with id exe:<path>). */
  'dock.pinPath': { params: DockPinPathParams; result: void };
}

